class Solution {
  private static long[] stats(long n) {
    long cnt = 0, sum = 0;
    for (int b = 0; b < 52; b++) {
      long blk = 1L << (b + 1), half = 1L << b;
      long c = (n + 1) / blk * half + Math.max(0, (n + 1) % blk - half);
      cnt += c;
      sum += c * b;
    }
    return new long[] {cnt, sum};
  }

  private static long prefixExp(long k) {
    long lo = 0, hi = 1L << 48;
    while (lo < hi) {
      long mid = (lo + hi + 1) >>> 1;
      if (stats(mid)[0] <= k) lo = mid;
      else hi = mid - 1;
    }
    long[] s = stats(lo);
    long rem = k - s[0], res = s[1], x = lo + 1;
    while (rem-- > 0) {
      int b = Long.numberOfTrailingZeros(x);
      res += b;
      x &= x - 1;
    }
    return res;
  }

  private static long pow2(long e, long mod) {
    long r = 1 % mod, b = 2 % mod;
    for (; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % mod;
      b = b * b % mod;
    }
    return r;
  }

  public int[] findProductsOfElements(long[][] queries) {
    int[] ans = new int[queries.length];
    for (int i = 0; i < queries.length; i++) {
      long e = prefixExp(queries[i][1] + 1) - prefixExp(queries[i][0]);
      ans[i] = (int) pow2(e, queries[i][2]);
    }
    return ans;
  }
}
